create table public.submissions (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,assignment_id uuid not null references public.assignments(id) on delete cascade,student_id uuid not null references public.students(id) on delete restrict,content text,attachment_url text,submitted_at timestamptz,reviewed_by_teacher_id uuid references public.teachers(id) on delete set null,reviewed_at timestamptz,feedback text,score numeric(8,2),created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(tenant_id,assignment_id,student_id));create index submissions_tenant_assignment_idx on public.submissions(tenant_id,assignment_id);alter table public.submissions enable row level security;revoke all on public.submissions from anon,authenticated;create policy submissions_select_tenant on public.submissions for select to authenticated using(tenant_id=public.current_tenant_id());
insert into public.permissions(code,name,description) values('submissions.read','Read submissions','View submissions'),('submissions.create','Create submissions','Create submissions'),('submissions.update','Update submissions','Review submissions') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER','STUDENT') and p.code like 'submissions.%' on conflict do nothing;
